insert into public.wards(name,code) values ('North Ward','NTH'),('Riverside Ward','RIV'),('Market Ward','MKT') on conflict(code) do nothing;
insert into public.poles(asset_tag,ward_id,location_note,latitude,longitude,status) select x.tag,w.id,x.loc,x.lat,x.lon,'active' from (values
('NTH-014','Outside 18 Cedar Lane',28.6139,77.2090,'North Ward'),('NTH-027','Cedar Lane crossing',28.6144,77.2096,'North Ward'),('NTH-041','Juniper Park east gate',28.6152,77.2078,'North Ward'),('NTH-063','Maple Street bus stop',28.6128,77.2110,'North Ward'),('RIV-008','Riverwalk footbridge',28.6200,77.2150,'Riverside Ward'),('RIV-022','Mill Road corner',28.6184,77.2131,'Riverside Ward'),('RIV-035','Canal steps',28.6220,77.2171,'Riverside Ward'),('MKT-011','Clocktower square',28.6250,77.2200,'Market Ward'),('MKT-019','Market Street arcade',28.6241,77.2213,'Market Ward'),('MKT-044','Old Depot entrance',28.6270,77.2182,'Market Ward')) as x(tag,loc,lat,lon,ward) join public.wards w on w.name=x.ward on conflict(asset_tag) do nothing;
